import dotenv from 'dotenv'
import { defineConfig } from 'prisma/config'

// Every workspace reads the single `.env` at the repo root.
dotenv.config({ path: '../../.env' })

export default defineConfig({
  schema: 'prisma',
  migrations: {
    // Written by hand, never generated by tools or agents.
    path: 'prisma/migrations',
    seed: 'tsx prisma/seeds/seed.ts',
  },
  datasource: {
    // Not `env('DATABASE_URL')`: `prisma generate` (run by typecheck and build,
    // in CI too) needs no database and must work without one.
    url: process.env.DATABASE_URL ?? '',
  },
})
